+import { useCustomReactQuery } from '@sixshop3-fe/shared/hooks';
+import { formatEndpoint } from '@sixshop3-fe/shared/utils';
+import useRestockQuery, {
+  fetchExistRestock,
+} from '@sixshop3-fe/theme-universe/api/src/lib/restock/rest/useRestockQuery';
+import { QUERY_KEY } from '@sixshop3-fe/theme-universe/constants';
+import { websiteApi, websiteAuth } from '@sixshop3-fe/theme-universe/utils';
+
+jest.mock('@sixshop3-fe/shared/hooks', () => ({
+  useCustomReactQuery: jest.fn(),
+}));
+
+jest.mock('@sixshop3-fe/theme-universe/utils', () => ({
+  getEndpointSet: jest.fn(() => ({
+    EXIST_RESTOCK: '/restock/subscription/exists',
+  })),
+  websiteApi: {
+    get: jest.fn(),
+  },
+  websiteAuth: {
+    getToken: jest.fn(),
+  },
+}));
+
+jest.mock('@sixshop3-fe/shared/utils', () => ({
+  formatEndpoint: jest.fn(),
+}));
+
+const mockedFormatEndpoint = jest.mocked(formatEndpoint);
+const mockedApiGet = jest.mocked(websiteApi.get);
+const mockedGetToken = jest.mocked(websiteAuth.getToken);
+const mockedUseCustomReactQuery = jest.mocked(useCustomReactQuery);
+
+describe('fetchExistRestock', () => {
+  beforeEach(() => {
+    jest.clearAllMocks();
+
+    mockedFormatEndpoint.mockReturnValue(
+      '/formatted/restock/subscription/exists' as unknown as ReturnType<typeof formatEndpoint>
+    );
+    mockedApiGet.mockResolvedValue({ data: { isUsed: true } });
+  });
+
+  it('비로그인 상태면 X-Customer-Usertoken 헤더를 보내지 않는다', async () => {
+    mockedGetToken.mockReturnValue(undefined);
+
+    await fetchExistRestock({
+      queryParam: { productId: 'product-id' },
+    });
+
+    expect(mockedApiGet).toHaveBeenCalledWith({
+      endpoint: '/formatted/restock/subscription/exists',
+      queryParam: { productId: 'product-id' },
+      option: undefined,
+    });
+  });
+
+  it('로그인 토큰이 있으면 X-Customer-Usertoken 헤더를 함께 전달한다', async () => {
+    mockedGetToken.mockReturnValue('customer-user-token');
+
+    await fetchExistRestock({
+      queryParam: { productId: 'product-id' },
+    });
+
+    expect(mockedApiGet).toHaveBeenCalledWith({
+      endpoint: '/formatted/restock/subscription/exists',
+      queryParam: { productId: 'product-id' },
+      option: {
+        headers: {
+          'X-Customer-Usertoken': 'customer-user-token',
+        },
+      },
+    });
+  });
+
+  it('로그인 토큰을 restock query key에 포함한다', () => {
+    mockedGetToken.mockReturnValue('customer-user-token');
+    mockedUseCustomReactQuery.mockReturnValue({
+      useCustomQuery: jest.fn(),
+    } as never);
+
+    useRestockQuery();
+
+    expect(mockedUseCustomReactQuery).toHaveBeenCalledWith([
+      QUERY_KEY.RESTOCK,
+      'customer-user-token',
+    ]);
+  });
+});

